@@ -1,4 +1,13 @@
 export function parseLimit(value, fallback = 20) {
-  const parsed = Number.parseInt(value, 10);
-  return Number.isFinite(parsed) ? parsed : fallback;
+  if (
+    typeof value !== "number" &&
+    (typeof value !== "string" || !/^\s*\d+\s*$/.test(value))
+  ) {
+    return fallback;
+  }
+
+  const parsed = Number(value);
+  return Number.isSafeInteger(parsed) && parsed >= 1 && parsed <= 100
+    ? parsed
+    : fallback;
 }

diff --git a/app.mjs b/app.mjs
index 4b16644..e37418c 100644
--- a/app.mjs
+++ b/app.mjs
@@ -1 +1,50 @@
 export const pageReady = true;
+
+export function setMenuOpen(button, menu, open) {
+  menu.hidden = !open;
+  button.setAttribute("aria-expanded", String(open));
+}
+
+if (typeof document !== "undefined") {
+  const menuButton = document.querySelector(".menu-button");
+  const menu = document.querySelector("#primary-nav");
+  const search = document.querySelector("#project-search");
+  const filters = [...document.querySelectorAll(".filter")];
+  const cards = [...document.querySelectorAll(".project-card")];
+  const count = document.querySelector("#result-count");
+  const empty = document.querySelector(".empty-state");
+  let currentFilter = "all";
+
+  const desktop = window.matchMedia("(min-width: 48rem)");
+  const syncMenu = () => setMenuOpen(menuButton, menu, desktop.matches);
+  syncMenu();
+  desktop.addEventListener?.("change", syncMenu);
+  menuButton.addEventListener("click", () => setMenuOpen(menuButton, menu, menu.hidden));
+  menu.addEventListener("click", (event) => {
+    if (!desktop.matches && event.target.closest("a")) setMenuOpen(menuButton, menu, false);
+  });
+
+  const updateProjects = () => {
+    const query = search.value.trim().toLowerCase();
+    let visible = 0;
+    cards.forEach((card) => {
+      const matchesFilter = currentFilter === "all" || card.dataset.status === currentFilter;
+      const matchesSearch = !query || card.dataset.search.includes(query);
+      card.hidden = !(matchesFilter && matchesSearch);
+      if (!card.hidden) visible += 1;
+    });
+    count.textContent = `${visible} ${visible === 1 ? "project" : "projects"}`;
+    empty.hidden = visible !== 0;
+  };
+
+  search.addEventListener("input", updateProjects);
+  filters.forEach((button) => button.addEventListener("click", () => {
+    currentFilter = button.dataset.filter;
+    filters.forEach((item) => {
+      const selected = item === button;
+      item.classList.toggle("active", selected);
+      item.setAttribute("aria-pressed", String(selected));
+    });
+    updateProjects();
+  }));
+}
